[
  "import {
  estimateTokens,
  type ContextEditEntry,
  type ExtensionContext,
  type ProjectedSessionEntry,
  type SessionEntry,
} from "@earendil-works/pi-coding-agent";

import { resultEdits, type ResultEdits } from "./result-edits.js";

export type SessionReader = ExtensionContext["sessionManager"];
/** The session reads a context view needs, so a view can describe an earlier leaf. */
export type ContextSource = Pick<
  SessionReader,
  "getBranch" | "buildSessionProjection" | "getLeafId"
>;
export type AgentMessage = ProjectedSessionEntry["messages"][number];
export type AssistantMessage = Extract<AgentMessage, { role: "assistant" }>;
/** A message the model reads as conversation rather than prompt and tool state. */
export type ModelMessage = Exclude<AgentMessage, { role: "system" }>;

export function isModelMessage(message: AgentMessage): message is ModelMessage {
  return message.role !== "system";
}
export type EditableContent = NonNullable<ContextEditEntry["replacement"]>["content"];

export const NOTE_TYPE = "pit.note";
export const NOTICE_TYPE = "pit.context-pressure";
export const PROVENANCE_TYPE = "pit.context-edit";
export const ELIDED_PREFIX = "[Elided by the model";
/** Starts the stub that replaces an elided assistant entry's tool-call arguments. */
export const ELIDED_CALLS_PREFIX = "[Pit: elided tool call";
export const SUMMARY_PREFIX = "[Model summary of ";

export type ContextRole =
  | "user"
  | "assistant"
  | "toolResult"
  | "note"
  | "notice"
  | "custom"
  | "bash"
  | "summary";
export const CONTEXT_ROLES: readonly ContextRole[] = [
  "user",
  "assistant",
  "toolResult",
  "note",
  "notice",
  "custom",
  "bash",
  "summary",
];

export type ContextState = "original" | "elided" | "summarized" | "replaced";
/** Operations the model can stage. */
export type ContextOperation = "elide" | "summarize" | "note";

/**
 * How the active model's provider caches the prompt, which decides what an edit re-prefills:
 * `breakpoints` providers cache only at explicit breakpoints after the system prompt and the last
 * user message, so changing an earlier entry rewrites the whole conversation; `prefix` providers
 * reuse the longest unchanged prefix; `unknown` uses the breakpoint estimate as an upper bound.
 */
export type CacheMode = "breakpoints" | "prefix" | "unknown";

/** One operation recorded in a `pit.context-edit` provenance entry. */
export interface ProvenanceOperation {
  toolCallId: string;
  operation: ContextOperation;
  targets: string[];
  /** Summarize: the entry carrying the summary. */
  carrier?: string;
  /** Summarize: every entry the summary replaced, including the carrier. */
  covers?: string[];
  key?: string;
  /** Note: `pruned` drops superseded note entries in the same batch as a rewrite. */
  action?: "created" | "replaced" | "removed" | "pruned";
  reason?: string;
  /** The caching mode the estimate assumed. */
  cacheMode: CacheMode;
  /** Elide: how many targets were assistant entries whose tool-call arguments it stubbed. */
  toolCallEntries?: number;
  tokensFreed: number;
  reprefillTokens: number;
}

export interface ProvenanceData {
  version: 1;
  operations: ProvenanceOperation[];
}

/** A model-visible contribution of one session entry. */
export interface ContextItem {
  readonly id: string;
  readonly entry: SessionEntry;
  readonly role: ContextRole;
  readonly messages: readonly ModelMessage[];
  readonly tokens: number;
  readonly state: ContextState;
  /** Tools called (assistant) or answered (tool result). */
  readonly tools: readonly string[];
  readonly toolCallIds: readonly string[];
  readonly noteKey?: string;
  /** Notes: the version this entry carries. */
  readonly noteVersion?: number;
  /** Notes: the entry records the key's removal. */
  readonly noteRemoved?: boolean;
  readonly noticeLevel?: number;
  /** Tool results: the file edits the call's program applied. */
  readonly edits?: ResultEdits;
  /** Why the model may never elide or summarize this entry. */
  readonly protectedReason?: string;
}

export interface ContextView {
  /** Model-visible entries in context order, without prompt and tool system messages. */
  readonly items: readonly ContextItem[];
  readonly byId: ReadonlyMap<string, ContextItem>;
  /** Each visible tool result, by the ID of the call it answers. */
  readonly results: ReadonlyMap<string, ContextItem>;
  readonly branchIds: ReadonlySet<string>;
  /** Entries the latest compaction keeps in context, whether visible or omitted. */
  readonly contextIds: ReadonlySet<string>;
  readonly latestEdits: ReadonlyMap<string, ContextEditEntry>;
  /** Summary carrier ID to the IDs its summary covers. */
  readonly summaries: ReadonlyMap<string, readonly string[]>;
  readonly summaryOf: ReadonlyMap<string, string>;
  readonly leafId: string | null;
  /** Estimated tokens of the prompt and tool system messages that precede the conversation. */
  readonly systemTokens: number;
  readonly tokens: number;
}

const PROTECTED: Partial<Record<ContextRole, string>> = {
  user: "user message",
  bash: "user shell command",
  custom: "extension message",
  summary: "compaction or branch summary",
  note: "model note; use session.setNote",
};

function record(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function firstText(content: EditableContent): string {
  if (typeof content === "string") return content;
  const block = content.find((part) => part.type === "text");
  return block?.type === "text" ? block.text : "";
}

/**
 * The raw content an entry contributed before any context edit. Callers pass only entries Pi
 * lets edits target: user, assistant, and tool-result messages, and custom messages.
 */
function originalContent(entry: SessionEntry): EditableContent {
  if (entry.type === "custom_message") return entry.content;
  return (entry as { message: { content: EditableContent } }).message.content;
}

/** Whether replacement content is an assistant message whose tool calls became an elision note. */
function elidedCalls(content: EditableContent): boolean {
  if (typeof content === "string") return false;
  return content.some(
    (block) =>
      block.type === "text" && (block as { text: string }).text.startsWith(ELIDED_CALLS_PREFIX),
  );
}

function stateOf(entry: SessionEntry, edit: ContextEditEntry | undefined): ContextState {
  if (!edit?.replacement) return "original";
  const { content } = edit.replacement;
  const text = firstText(content);
  if (text.startsWith(ELIDED_PREFIX)) return "elided";
  // A summary carrier stays summarized even if its tool call was later stubbed.
  if (text.startsWith(SUMMARY_PREFIX)) return "summarized";
  if (elidedCalls(content)) return "elided";
  return JSON.stringify(content) === JSON.stringify(originalContent(entry))
    ? "original"
    : "replaced";
}

/** Message entries Pi's API can append; anything else reads as a protected extension message. */
function messageRole(message: ModelMessage): ContextRole {
  if (message.role === "bashExecution") return "bash";
  const { role } = message;
  return role === "user" || role === "assistant" || role === "toolResult" ? role : "custom";
}

/** The role of a content-bearing entry: a message, custom message, or summary. */
export function entryRole(entry: SessionEntry): ContextRole {
  if (entry.type === "custom_message") {
    if (entry.customType === NOTE_TYPE) return "note";
    return entry.customType === NOTICE_TYPE ? "notice" : "custom";
  }
  return entry.type === "message" ? messageRole(entry.message as ModelMessage) : "summary";
}

export function toolsOf(messages: readonly AgentMessage[]): {
  tools: string[];
  toolCallIds: string[];
} {
  const tools: string[] = [];
  const toolCallIds: string[] = [];
  for (const message of messages) {
    if (message.role === "toolResult") {
      tools.push(message.toolName);
      toolCallIds.push(message.toolCallId);
    } else if (message.role === "assistant") {
      for (const block of message.content) {
        if (block.type !== "toolCall") continue;
        if (!tools.includes(block.name)) tools.push(block.name);
        toolCallIds.push(block.id);
      }
    }
  }
  return { tools, toolCallIds };
}

function customDetails(entry: SessionEntry): Record<string, unknown> | undefined {
  return entry.type === "custom_message" ? record(entry.details) : undefined;
}

function contextItem(
  projected: ProjectedSessionEntry,
  edit: ContextEditEntry | undefined,
  currentTurn: ReadonlySet<string>,
): ContextItem | undefined {
  const messages = projected.messages.filter(isModelMessage);
  if (messages.length === 0) return undefined;
  const entry = projected.sourceEntry;
  const role = entryRole(entry);
  const details = customDetails(entry);
  const protectedReason = currentTurn.has(entry.id) ? "current turn" : PROTECTED[role];
  // A tool result is always a message entry.
  const edits =
    role === "toolResult"
      ? resultEdits(entry as Extract<SessionEntry, { type: "message" }>)
      : undefined;
  return {
    id: entry.id,
    entry,
    role,
    messages,
    tokens: messages.reduce((sum, message) => sum + estimateTokens(message), 0),
    state: stateOf(entry, edit),
    ...toolsOf(messages),
    ...(role === "note" && typeof details?.key === "string"
      ? {
          noteKey: details.key,
          noteVersion: typeof details.version === "number" ? details.version : 1,
          ...(details.removed === true ? { noteRemoved: true } : {}),
        }
      : {}),
    ...(role === "notice" && typeof details?.level === "number"
      ? { noticeLevel: details.level }
      : {}),
    ...(edits ? { edits } : {}),
    ...(protectedReason ? { protectedReason } : {}),
  };
}

function lastIndex<T>(values: readonly T[], predicate: (value: T) => boolean): number {
  for (let index = values.length - 1; index >= 0; index--) {
    if (predicate(values[index] as T)) return index;
  }
  return -1;
}

function callsTool(entry: SessionEntry, toolCallId?: string): boolean {
  if (entry.type !== "message" || entry.message.role !== "assistant") return false;
  return (
    toolCallId === undefined ||
    entry.message.content.some((block) => block.type === "toolCall" && block.id === toolCallId)
  );
}

/**
 * The entries of the turn that is running a tool call: its assistant message and everything
 * after it. Without a matching call, the latest assistant message starts the turn.
 */
function currentTurnIds(branch: readonly SessionEntry[], toolCallId: string): Set<string> {
  let start = lastIndex(branch, (entry) => callsTool(entry, toolCallId));
  if (start < 0) start = lastIndex(branch, (entry) => callsTool(entry));
  return new Set(start < 0 ? [] : branch.slice(start).map((entry) => entry.id));
}

function recordProvenance(data: unknown, summaries: Map<string, readonly string[]>): void {
  const operations = record(data)?.operations;
  if (!Array.isArray(operations)) return;
  for (const value of operations) {
    const operation = record(value);
    if (!operation || typeof operation.carrier !== "string") continue;
    const covers: unknown[] = Array.isArray(operation.covers) ? operation.covers : [];
    summaries.set(
      operation.carrier,
      covers.filter((id): id is string => typeof id === "string"),
    );
  }
}

interface ContextViewOptions {
  /** Protects the turn running this tool call from edits. */
  toolCallId?: string;
}

export function buildContextView(
  session: ContextSource,
  options: ContextViewOptions = {},
): ContextView {
  const branch = session.getBranch();
  const projection = session.buildSessionProjection();
  const latestEdits = new Map<string, ContextEditEntry>();
  const summaries = new Map<string, readonly string[]>();
  const contextIds = new Set<string>();
  for (const { sourceEntry } of projection.entries) {
    contextIds.add(sourceEntry.id);
    if (sourceEntry.type === "context_edit") {
      latestEdits.set(sourceEntry.targetId, sourceEntry);
    } else if (sourceEntry.type === "custom" && sourceEntry.customType === PROVENANCE_TYPE) {
      recordProvenance(sourceEntry.data, summaries);
    }
  }
  const summaryOf = new Map<string, string>();
  for (const [carrier, covers] of summaries) {
    for (const id of covers) summaryOf.set(id, carrier);
  }
  const currentTurn =
    options.toolCallId === undefined
      ? new Set<string>()
      : currentTurnIds(branch, options.toolCallId);
  const items = projection.entries
    .map((projected) =>
      contextItem(projected, latestEdits.get(projected.sourceEntry.id), currentTurn),
    )
    .filter((item): item is ContextItem => item !== undefined);
  return {
    items,
    byId: new Map(items.map((item) => [item.id, item])),
    results: new Map(
      items.flatMap((item) =>
        item.role === "toolResult" ? item.toolCallIds.map((id) => [id, item] as const) : [],
      ),
    ),
    branchIds: new Set(branch.map((entry) => entry.id)),
    contextIds,
    latestEdits,
    summaries,
    summaryOf,
    leafId: session.getLeafId(),
    tokens: items.reduce((sum, item) => sum + item.tokens, 0),
    systemTokens: projection.entries.reduce(
      (sum, { messages }) =>
        sum +
        messages.reduce(
          (total, message) => total + (message.role === "system" ? estimateTokens(message) : 0),
          0,
        ),
      0,
    ),
  };
}
",
  "import { estimateTokens } from "@earendil-works/pi-coding-agent";

import {
  describeMissing,
  formatTokens,
  type PlannedEdit,
  PlanProblems,
  reprefillAfter,
  type CacheBasis,
} from "./planning.js";
import { callEdits, type ResultEdits } from "./result-edits.js";
import {
  type AgentMessage,
  type AssistantMessage,
  type ContextItem,
  type ContextView,
  ELIDED_CALLS_PREFIX,
  ELIDED_PREFIX,
  type EditableContent,
} from "./view.js";

export const MAX_REASON_CHARS = 200;

export function elisionStub(id: string, tokens: number, reason?: string): string {
  const because = reason ? ` · reason: ${reason}` : "";
  return `${ELIDED_PREFIX} · ~${formatTokens(tokens)} tokens${because} · original: session.inspectEntry("${id}")]`;
}

/** The results that answer an assistant entry's tool calls, in call order. */
function callResults(view: ContextView, item: ContextItem): ContextItem[] {
  return item.toolCallIds.flatMap((id) => {
    const result = view.results.get(id);
    return result ? [result] : [];
  });
}

/**
 * The note that replaces an elided entry's tool calls and their results. It is plain text, not a
 * tool call, so a model sees nothing it could copy as a call (#292), and it reads as an omission,
 * not as code, so a model does not mistake it for a program that ran (#222).
 */
function callNote(view: ContextView, item: ContextItem, reason?: string): string {
  const message = item.messages[0] as AssistantMessage;
  const names = message.content.flatMap((block) => (block.type === "toolCall" ? [block.name] : []));
  const results = callResults(view, item);
  const tokens = argumentTokens(message) + results.reduce((sum, result) => sum + result.tokens, 0);
  const failed = results.filter(
    (result) => (result.messages[0] as { isError?: boolean }).isError === true,
  ).length;
  const edits = callEdits(view, item);
  const label =
    names.length === 1
      ? `${ELIDED_CALLS_PREFIX}: ${names[0]}`
      : `${ELIDED_CALLS_PREFIX}s: ${names.join(", ")}`;
  const withResults =
    results.length === 0 ? "" : results.length === 1 ? " with its result" : " with their results";
  const parts = [
    `${label} · ~${formatTokens(tokens)} tokens${withResults}`,
    ...(edits ? [appliedEdits(edits)] : []),
    ...(failed > 0 ? [`${failed} failed`] : []),
    ...(reason ? [`reason: ${reason}`] : []),
    `originals: ${[item.id, ...results.map((result) => result.id)].map((id) => `session.inspectEntry("${id}")`).join(", ")}`,
  ];
  return `${parts.join(" · ")}]`;
}

const MAX_STUB_FILES = 6;
const MAX_STUB_PATH_CHARS = 120;

/** Which files an elided call's edits changed, so the trail stays readable without its payload. */
function appliedEdits(edits: ResultEdits): string {
  const shown = edits.files.slice(0, MAX_STUB_FILES).map((edit) => {
    const file =
      edit.file.length > MAX_STUB_PATH_CHARS
        ? `…${edit.file.slice(-MAX_STUB_PATH_CHARS)}`
        : edit.file;
    if (edit.deleted) return `${file} deleted`;
    const changes = `${edit.applied} change${edit.applied === 1 ? "" : "s"}`;
    return `${file} @ ${edit.revision} (${changes})`;
  });
  const more = edits.count - shown.length;
  return `applied: ${shown.join(", ")}${more > 0 ? `, +${more} more` : ""}`;
}

/** Tokens of an assistant message's tool-call arguments, which elide replaces with a stub. */
export function argumentTokens(message: AssistantMessage): number {
  const calls = message.content.filter((block) => block.type === "toolCall");
  return calls.reduce((sum, block) => sum + estimateTokens({ ...message, content: [block] }), 0);
}

/**
 * An assistant message whose tool calls become one note, where the first call was. Text and
 * thinking stay, so signed thinking still replays; the calls' results are omitted with them, so
 * every remaining result still answers a call.
 */
function foldedAssistant(message: AssistantMessage, note: string): AssistantMessage {
  const content: AssistantMessage["content"] = [];
  for (const block of message.content) {
    if (block.type !== "toolCall") content.push(block);
    else if (!content.some((kept) => kept.type === "text" && kept.text === note))
      content.push({ type: "text", text: note });
  }
  return { ...message, content };
}

function stubbed(message: AgentMessage, stub: string): AgentMessage {
  if (message.role === "toolResult") return { ...message, content: [{ type: "text", text: stub }] };
  return message.role === "assistant" ? foldedAssistant(message, stub) : message;
}

/** Tokens of an entry after elision replaces its result or tool-call arguments with a stub. */
export function stubTokens(item: ContextItem, stub: string): number {
  return item.messages.reduce((sum, message) => sum + estimateTokens(stubbed(message, stub)), 0);
}

function elisionProblem(item: ContextItem, stubSize: number, size: number): string | undefined {
  if (item.protectedReason) return `${item.id} is protected: ${item.protectedReason}`;
  if (item.role === "assistant") {
    if (item.toolCallIds.length === 0) {
      return `${item.id} is an assistant entry without tool calls; elide shrinks tool results and tool-call arguments, and session.summarize replaces assistant turns`;",
  "import type { ToolExecutionApi } from "@earendil-works/pi-durable";

export type Tx = Parameters<Parameters<ToolExecutionApi["commit"]>[0]>[0];
export type EntryRecord = Awaited<ReturnType<Tx["scanEntries"]>>["items"][number];
export type EntryId = EntryRecord["id"];
export type Message = NonNullable<EntryRecord["model"]>[number];
export type AssistantMessage = Extract<Message, { role: "assistant" }>;
export type ContextEdit = NonNullable<EntryRecord["edits"]>[number];
type ToolContext = Parameters<ToolExecutionApi["commit"]>[1];

/** Pit's applied context edits: the entry that carries a rewrite and what it did. */
export const EDIT_KIND = "pit.context-edit";
/** A rewrite staged for the end of the run, applied by the entry that lists it. */
export const PENDING_EDIT_KIND = "pit.context-edit-pending";

export const ELIDED_PREFIX = "[Elided by the model";
export const ELIDED_CALLS_PREFIX = "[Pit: elided tool call";
export const COLLAPSED_CALLS_PREFIX = "[Pit: collapsed ";
export const SUMMARY_PREFIX = "[Model summary of ";

export type ContextRole = "user" | "assistant" | "toolResult" | "custom" | "summary";
export type ContextState = "original" | "elided" | "summarized" | "replaced";
export type ContextOperation = "elide" | "summarize" | "collapse";

/** What Pit records with each rewrite, so an outline can say what changed an entry. */
export interface EditProvenance {
  operation: ContextOperation;
  targets: string[];
  /** Summarize: the entry carrying the summary. */
  carrier?: string;
  /** Every entry the rewrite changed. */
  covers: string[];
  reason?: string;
  tokensFreed: number;
}

/** One model-visible entry of the active context. */
export interface ContextItem {
  readonly id: string;
  readonly entry: EntryRecord;
  readonly role: ContextRole;
  /** Messages the model sees now, after edits. */
  readonly messages: readonly Message[];
  readonly tokens: number;
  readonly state: ContextState;
  readonly tools: readonly string[];
  readonly toolCallIds: readonly string[];
  readonly protectedReason?: string;
  /** Summary carriers: the entries the summary replaced. */
  readonly covers?: readonly string[];
}

export interface ContextView {
  /** Model-visible entries in context order, without system entries. */
  readonly items: readonly ContextItem[];
  readonly byId: ReadonlyMap<string, ContextItem>;
  /** Each visible tool result, by the ID of the call it answers. */
  readonly results: ReadonlyMap<string, ContextItem>;
  /** Entries in the active range, whether or not an edit hides them. */
  readonly activeIds: ReadonlySet<string>;
  /** Targets of rewrites staged for the end of the run, by operation. */
  readonly pending: ReadonlyMap<string, ContextOperation>;
  readonly tailId: string | undefined;
  /** Estimated tokens of system entries: the prompt, sections, and tools. */
  readonly systemTokens: number;
  readonly tokens: number;
}

const SCAN_PAGE = 256;
// Assistant messages pi-durable leaves out of the model context.
const EXCLUDED_STOP_REASONS = new Set(["aborted", "error", "deferred"]);
// pi-ai's image estimate, as Pi's token heuristic uses.
const IMAGE_TOKENS = 1_200;

const PROTECTED: Partial<Record<ContextRole, string>> = {
  user: "user message",
  custom: "host message",
  summary: "compaction summary",
};

/** Pi's heuristic: about four characters per token, and a fixed cost per image. */
export function messageTokens(message: Message): number {
  let chars = 0;
  let images = 0;
  const content: unknown = message.content;
  if (typeof content === "string") chars += content.length;
  else if (Array.isArray(content)) {
    for (const block of content as Array<Record<string, unknown>>) {
      if (block.type === "text") chars += String(block.text).length;
      else if (block.type === "thinking") chars += String(block.thinking).length;
      else if (block.type === "toolCall") {
        chars += String(block.name).length + JSON.stringify(block.arguments).length;
      } else if (block.type === "image") images += 1;
    }
  }
  return Math.ceil(chars / 4) + images * IMAGE_TOKENS;
}

export function messagesTokens(messages: readonly Message[]): number {
  return messages.reduce((sum, message) => sum + messageTokens(message), 0);
}

function contributes(message: Message): boolean {
  return !(message.role === "assistant" && EXCLUDED_STOP_REASONS.has(message.stopReason));
}

function roleOf(entry: EntryRecord, message: Message): ContextRole {
  if (entry.kind === "pi.compaction") return "summary";
  if (message.role === "assistant") return "assistant";
  if (message.role === "toolResult") return "toolResult";
  return entry.kind === "pi.user" ? "user" : "custom";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function provenanceOf(entry: EntryRecord): EditProvenance[] {
  const data = entry.data;
  if (!isRecord(data) || !Array.isArray(data.operations)) return [];
  return data.operations.filter(isRecord) as unknown as EditProvenance[];
}

/** The entries from the newest head marker through the tail. */
export interface ActiveRange {
  head: EntryRecord | undefined;
  entries: EntryRecord[];
}

/** Reads the active range in the caller's commit. */
export async function readActiveEntries(
  tx: Pick<Tx, "latestHeadMarker" | "scanEntries">,
  conversationId: EntryRecord["conversationId"],
): Promise<ActiveRange> {
  const head = await tx.latestHeadMarker(conversationId);
  const entries: EntryRecord[] = [];
  const query = {
    conversationId,
    order: "ascending",
    ...(head?.head === undefined ? {} : { minEntryId: head.head }),
  } as const;
  let page = await tx.scanEntries(query, SCAN_PAGE);
  entries.push(...page.items);
  while (page.next !== undefined) {
    page = await tx.scanEntries(query, SCAN_PAGE, page.next);
    entries.push(...page.items);
  }
  return { head, entries };
}

/** The newest edit of each target, what Pit recorded about it, and rewrites still staged. */
function collectEdits(entries: readonly EntryRecord[]) {
  const edits = new Map<EntryId, { edit: ContextEdit; by: EntryRecord }>();
  const provenance = new Map<string, EditProvenance>();
  const pendingEntries: EntryRecord[] = [];
  const applied = new Set<string>();
  for (const entry of entries) {
    for (const edit of entry.edits ?? []) edits.set(edit.target, { edit, by: entry });
    for (const operation of provenanceOf(entry)) {
      for (const target of operation.covers) provenance.set(target, operation);
    }
    if (entry.kind === PENDING_EDIT_KIND) pendingEntries.push(entry);
    if (entry.kind === EDIT_KIND && isRecord(entry.data) && Array.isArray(entry.data.pending)) {
      for (const id of entry.data.pending) applied.add(String(id));
    }
  }
  const pending = new Map<string, ContextOperation>();
  for (const entry of pendingEntries) {
    if (applied.has(String(entry.id))) continue;
    for (const operation of provenanceOf(entry)) {
      for (const target of operation.covers) {
        pending.set(target, operation.operation);
      }
    }
  }
  return { edits, provenance, pending };
}

/** The active context of a running call, read in one commit; its turn is protected. */
export async function readContextView(
  api: Pick<ToolExecutionApi, "commit" | "conversationId">,
  context: ToolContext,
  callId: string,
): Promise<ContextView> {
  const range = await api.commit((tx) => readActiveEntries(tx, api.conversationId), context);
